// CACHE-ASIDE: Lazy loading
async getLesson(id) {
  const cached = await cache.get(`lesson:${id}`);
  if (cached) return cached; // Hit
  const lesson = await db.findLesson(id); // Miss, vai ao banco
  await cache.set(`lesson:${id}`, lesson, 3600);
  return lesson;
}

// WRITE-THROUGH: Escrita síncrona
async updateLesson(id, data) {
  await cache.set(`lesson:${id}`, data);
  await db.updateLesson(id, data); // Bloqueia
  return data;
}

// WRITE-BEHIND: Escrita assíncrona
async updateLesson(id, data) {
  await cache.set(`lesson:${id}`, data); // Rápido
  this.queue.enqueue('persist-lesson', {id, data}); // Background
  return data; // Retorna imediatamente
}

