async explainError(questionId, studentError) {
  // 1. Cache-Aside: tenta cache
  const cacheKey = `explanation:${questionId}`;
  const cached = await cache.get(cacheKey);
  if (cached) return cached;

  // 2. Write-Through: verifica quota
  const quotaKey = `quota:${today}`;
  if (await redis.get(quotaKey) >= 10000) {
    return { explanation: 'Limite atingido' };
  }

  // 3. Chamar IA (operação cara)
  const explanation = await ai.generate(questionId, studentError);

  // 4. Write-Behind: persiste em background
  queue.enqueue('persist-explanation', {questionId, explanation});

  // 5. Atualizar cache e quota
  await Promise.all([
    cache.setex(cacheKey, 7*24*3600, explanation),
    redis.incr(quotaKey)
  ]);

  return explanation;
}

